//! Virtual Machine for executing compiled Verilog-A bytecode
//!
//! This module provides a stack-based VM that executes bytecode programs
//! generated by the code generator. It handles voltage/current access,
//! parameter lookup, and mathematical operations.

use crate::codegen::{BytecodeProgram, Instruction};

/// Execution context providing runtime state to the VM
#[derive(Debug, Clone)]
pub struct VmContext {
    /// Node voltages (indexed by terminal)
    pub voltages: Vec<f64>,
    /// Internal node voltages (for nodes not in port list)
    pub internal_voltages: Vec<f64>,
    /// Branch currents
    pub currents: Vec<f64>,
    /// Parameter values (indexed by parameter)
    pub parameters: Vec<f64>,
    /// Variable values (indexed by variable)
    pub variables: Vec<f64>,
    /// Current simulation time
    pub time: f64,
    /// Temperature in Kelvin
    pub temperature: f64,
}

impl Default for VmContext {
    fn default() -> Self {
        Self {
            voltages: Vec::new(),
            internal_voltages: Vec::new(),
            currents: Vec::new(),
            parameters: Vec::new(),
            variables: Vec::new(),
            time: 0.0,
            temperature: 300.15, // 27°C default
        }
    }
}

impl VmContext {
    /// Create a new VM context with specified terminal count
    pub fn new(num_terminals: usize) -> Self {
        Self {
            voltages: vec![0.0; num_terminals],
            internal_voltages: Vec::new(),
            currents: Vec::new(),
            parameters: Vec::new(),
            variables: Vec::new(),
            time: 0.0,
            temperature: 300.15,
        }
    }

    /// Create with internal nodes
    pub fn with_internal_nodes(num_terminals: usize, num_internal: usize) -> Self {
        Self {
            voltages: vec![0.0; num_terminals],
            internal_voltages: vec![0.0; num_internal],
            currents: Vec::new(),
            parameters: Vec::new(),
            variables: Vec::new(),
            time: 0.0,
            temperature: 300.15,
        }
    }

    /// Get the voltage difference between two terminals
    #[inline]
    pub fn voltage(&self, pos: usize, neg: usize) -> f64 {
        let v_pos = self.voltages.get(pos).copied().unwrap_or(0.0);
        let v_neg = self.voltages.get(neg).copied().unwrap_or(0.0);
        v_pos - v_neg
    }

    /// Get internal node voltage
    #[inline]
    pub fn internal_voltage(&self, idx: usize) -> f64 {
        self.internal_voltages.get(idx).copied().unwrap_or(0.0)
    }

    /// Get current between terminals (placeholder)
    #[inline]
    pub fn current(&self, pos: usize, neg: usize) -> f64 {
        // For now, currents are computed from branch equations
        let _ = (pos, neg);
        self.currents.first().copied().unwrap_or(0.0)
    }

    /// Get thermal voltage kT/q
    #[inline]
    pub fn vt(&self) -> f64 {
        const K_BOLTZMANN: f64 = 1.380649e-23;
        const Q_ELECTRON: f64 = 1.602176634e-19;
        K_BOLTZMANN * self.temperature / Q_ELECTRON
    }

    /// Set a parameter value
    pub fn set_param(&mut self, index: usize, value: f64) {
        if index >= self.parameters.len() {
            self.parameters.resize(index + 1, 0.0);
        }
        self.parameters[index] = value;
    }

    /// Set a variable value
    pub fn set_variable(&mut self, index: usize, value: f64) {
        if index >= self.variables.len() {
            self.variables.resize(index + 1, 0.0);
        }
        self.variables[index] = value;
    }
}

/// Stack-based virtual machine for bytecode execution
pub struct Vm<'a> {
    /// Execution context
    context: &'a VmContext,
    /// Evaluation stack
    stack: Vec<f64>,
}

impl<'a> Vm<'a> {
    /// Create a new VM with the given context
    pub fn new(context: &'a VmContext) -> Self {
        Self {
            context,
            stack: Vec::with_capacity(32),
        }
    }

    /// Execute a bytecode program and return the result
    pub fn execute(&mut self, program: &BytecodeProgram) -> Result<f64, VmError> {
        self.stack.clear();

        for instruction in &program.instructions {
            self.execute_instruction(instruction)?;
        }

        self.stack
            .pop()
            .ok_or(VmError::StackUnderflow("No result on stack"))
    }

    /// Execute a single instruction
    #[inline]
    fn execute_instruction(&mut self, instruction: &Instruction) -> Result<(), VmError> {
        match instruction {
            Instruction::PushConst(v) => {
                self.stack.push(*v);
            }
            Instruction::PushParam(idx) => {
                let v = self.context.parameters.get(*idx).copied().unwrap_or(0.0);
                self.stack.push(v);
            }
            Instruction::PushVoltage(pos, neg) => {
                self.stack.push(self.context.voltage(*pos, *neg));
            }
            Instruction::PushCurrent(pos, neg) => {
                self.stack.push(self.context.current(*pos, *neg));
            }
            Instruction::PushInternalVoltage(idx) => {
                self.stack.push(self.context.internal_voltage(*idx));
            }
            Instruction::PushVariable(idx) => {
                let v = self.context.variables.get(*idx).copied().unwrap_or(0.0);
                self.stack.push(v);
            }
            Instruction::PushTime => {
                self.stack.push(self.context.time);
            }
            Instruction::PushTemperature => {
                self.stack.push(self.context.temperature);
            }
            Instruction::PushVt => {
                self.stack.push(self.context.vt());
            }

            // Binary operations
            Instruction::Add => self.binary_op(|a, b| a + b)?,
            Instruction::Sub => self.binary_op(|a, b| a - b)?,
            Instruction::Mul => self.binary_op(|a, b| a * b)?,
            Instruction::Div => self.binary_op(|a, b| a / b)?,
            Instruction::Pow => self.binary_op(|a, b| a.powf(b))?,

            // Unary operations
            Instruction::Neg => self.unary_op(|a| -a)?,
            Instruction::Abs => self.unary_op(|a| a.abs())?,
            Instruction::Sqrt => self.unary_op(|a| a.sqrt())?,
            Instruction::Exp => self.unary_op(|a| a.exp())?,
            Instruction::Log => self.unary_op(|a| a.ln())?,
            Instruction::Log10 => self.unary_op(|a| a.log10())?,
            Instruction::Sin => self.unary_op(|a| a.sin())?,
            Instruction::Cos => self.unary_op(|a| a.cos())?,
            Instruction::Tan => self.unary_op(|a| a.tan())?,
            Instruction::Sinh => self.unary_op(|a| a.sinh())?,
            Instruction::Cosh => self.unary_op(|a| a.cosh())?,
            Instruction::Tanh => self.unary_op(|a| a.tanh())?,

            // Two-argument functions
            Instruction::Min => self.binary_op(|a, b| a.min(b))?,
            Instruction::Max => self.binary_op(|a, b| a.max(b))?,

            // Limited exponential for convergence
            // Uses linear extrapolation beyond the limit to prevent overflow
            // while maintaining C0 and C1 continuity
            Instruction::Limexp => self.unary_op(|a| {
                const LIMIT: f64 = 40.0; // exp(40) ≈ 2.4e17
                if a > LIMIT {
                    let exp_limit = LIMIT.exp();
                    // Linear extrapolation: f(x) = f(limit) + f'(limit) * (x - limit)
                    // For exp, f'(x) = exp(x), so f'(limit) = exp(limit)
                    exp_limit * (1.0 + a - LIMIT)
                } else if a < -LIMIT {
                    // For very negative values, return essentially 0
                    (-LIMIT).exp()
                } else {
                    a.exp()
                }
            })?,

            // Conditional: if cond != 0, use then_val, else else_val
            Instruction::IfElse => {
                let else_val = self.pop()?;
                let then_val = self.pop()?;
                let cond = self.pop()?;
                let result = if cond.abs() > 1e-15 {
                    then_val
                } else {
                    else_val
                };
                self.stack.push(result);
            }

            // Comparison operations (return 1.0 for true, 0.0 for false)
            Instruction::Gt => self.binary_op(|a, b| if a > b { 1.0 } else { 0.0 })?,
            Instruction::Lt => self.binary_op(|a, b| if a < b { 1.0 } else { 0.0 })?,
            Instruction::Ge => self.binary_op(|a, b| if a >= b { 1.0 } else { 0.0 })?,
            Instruction::Le => self.binary_op(|a, b| if a <= b { 1.0 } else { 0.0 })?,
            Instruction::Eq => {
                self.binary_op(|a, b| if (a - b).abs() < 1e-15 { 1.0 } else { 0.0 })?
            }
            Instruction::Ne => {
                self.binary_op(|a, b| if (a - b).abs() >= 1e-15 { 1.0 } else { 0.0 })?
            }

            // Logical operations
            Instruction::And => self.binary_op(|a, b| {
                if a.abs() > 1e-15 && b.abs() > 1e-15 {
                    1.0
                } else {
                    0.0
                }
            })?,
            Instruction::Or => self.binary_op(|a, b| {
                if a.abs() > 1e-15 || b.abs() > 1e-15 {
                    1.0
                } else {
                    0.0
                }
            })?,
            Instruction::Not => self.unary_op(|a| if a.abs() < 1e-15 { 1.0 } else { 0.0 })?,
        }
        Ok(())
    }

    /// Pop a value from the stack
    #[inline]
    fn pop(&mut self) -> Result<f64, VmError> {
        self.stack
            .pop()
            .ok_or(VmError::StackUnderflow("Stack underflow"))
    }

    /// Apply a unary operation
    #[inline]
    fn unary_op<F>(&mut self, f: F) -> Result<(), VmError>
    where
        F: FnOnce(f64) -> f64,
    {
        let a = self.pop()?;
        self.stack.push(f(a));
        Ok(())
    }

    /// Apply a binary operation
    #[inline]
    fn binary_op<F>(&mut self, f: F) -> Result<(), VmError>
    where
        F: FnOnce(f64, f64) -> f64,
    {
        let b = self.pop()?;
        let a = self.pop()?;
        self.stack.push(f(a, b));
        Ok(())
    }
}

/// VM execution errors
#[derive(Debug, Clone, PartialEq)]
pub enum VmError {
    StackUnderflow(&'static str),
    InvalidInstruction(&'static str),
}

impl std::fmt::Display for VmError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            VmError::StackUnderflow(msg) => write!(f, "Stack underflow: {}", msg),
            VmError::InvalidInstruction(msg) => write!(f, "Invalid instruction: {}", msg),
        }
    }
}

impl std::error::Error for VmError {}

